// ── Document Number Generator ─────────────────────────────────────────
function generateDocNumber(prefix) {
  prefix = (prefix || 'DOC').toUpperCase().trim();
  const year = new Date().getFullYear();
  let counters = {};
  try {
    const raw = localStorage.getItem('rh_doc_counters');
    if (raw) counters = JSON.parse(raw);
  } catch(e) {}

  const key = prefix + '_' + year;
  const current = (parseInt(counters[key]) || 0) + 1;
  counters[key] = current;
  try {
    localStorage.setItem('rh_doc_counters', JSON.stringify(counters));
  } catch(e) {}

  const seq = String(current).padStart(5, '0');
  return prefix + '-' + year + '-' + seq;
}

// ── Currency Formatter ─────────────────────────────────────────────────
function formatCurrency(amount, currency) {
  const val = parseFloat(amount) || 0;
  currency = (currency || 'PKR').toUpperCase().trim();
  try {
    return currency + ' ' + val.toLocaleString(undefined, {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    });
  } catch(e) {
    return currency + ' ' + val.toFixed(2);
  }
}

function _esc(str) {
  if (str === null || str === undefined) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function _todayDate() {
  const d = new Date();
  return String(d.getDate()).padStart(2, '0') + '/' + String(d.getMonth() + 1).padStart(2, '0') + '/' + d.getFullYear();
}

function _formatDate(dStr) {
  if (!dStr) return _todayDate();
  try {
    const p = dStr.split('T')[0].split('-');
    if (p.length === 3) return p[2] + '/' + p[1] + '/' + p[0];
  } catch(e) {}
  return dStr;
}

