// ═══════════════════════════════════════════════════════════════════════
// 1. PURCHASE INVOICE (Suppliers)
// ═══════════════════════════════════════════════════════════════════════
function buildPurchaseInvoice(supplier, transaction, payments) {
  supplier = supplier || {};
  transaction = transaction || {};
  payments = payments || [];

  const cur = supplier.currency || 'PKR';
  const docNo = transaction.invoice_no || 'PUR-DRAFT';
  const docDate = transaction.date || new Date().toISOString();

  // Line items
  const items = transaction.items || [];
  let itemsHtml = items.map((it, idx) => {
    const qty = parseFloat(it.qty) || 0;
    const rate = parseFloat(it.rate) || 0;
    const amt = parseFloat(it.amount) || (qty * rate);
    return `<tr>
      <td class="center">${idx + 1}</td>
      <td style="font-weight:600;">${_esc(it.desc || it.name || 'Stock item')}</td>
      <td class="center">${qty}</td>
      <td class="num">${formatCurrency(rate, cur)}</td>
      <td class="num" style="font-weight:700;">${formatCurrency(amt, cur)}</td>
    </tr>`;
  }).join('');

  if (!itemsHtml) {
    itemsHtml = '<tr><td colspan="5" style="text-align:center;color:#94a3b8;padding:16px;">No items specified.</td></tr>';
  }

  // Charges
  const subtotal = parseFloat(transaction.subtotal) || 0;
  const transport = parseFloat(transaction.transport) || 0;
  const loading = parseFloat(transaction.loading) || 0;
  const tax = parseFloat(transaction.tax) || 0;
  const discount = parseFloat(transaction.discount) || 0;
  const grandTotal = parseFloat(transaction.grand_total) || 0;

  // Payments on this transaction
  const paid = payments.reduce((sum, p) => sum + (parseFloat(p.amount) || 0), 0);
  const remaining = Math.max(0, grandTotal - paid);

  let paymentsSection = '';
  if (payments.length > 0) {
    const payRows = payments.map((p, idx) => `<tr>
      <td class="center">${idx + 1}</td>
      <td style="font-weight:700;">${_esc(p.receipt_no || 'PV-REC')}</td>
      <td>${_formatDate(p.date)}</td>
      <td>${_esc(p.payment_method || 'Cash')} ${p.bank_ref ? ' - Ref: ' + _esc(p.bank_ref) : ''}</td>
      <td class="num" style="font-weight:700; color:#059669;">${formatCurrency(p.amount, cur)}</td>
    </tr>`).join('');

    paymentsSection = `
      <div style="margin-top:14px; margin-bottom:12px;">
        <div style="font-size:10px; font-weight:800; text-transform:uppercase; color:#000; margin-bottom:4px;">Payment Records Against This Invoice</div>
        <table class="doc-table">
          <thead>
            <tr>
              <th style="width:30px;" class="center">#</th>
              <th>Voucher #</th>
              <th>Date</th>
              <th>Method / Reference</th>
              <th class="num">Amount Paid</th>
            </tr>
          </thead>
          <tbody>${payRows}</tbody>
        </table>
      </div>
    `;
  }

  const body = `
    ${_renderHeader('PURCHASE INVOICE', docNo, docDate, 'Supplier Vendor Delivery &bull; Stock Inbound')}

    <div class="party-grid">
      <div class="party-box party-primary">
        <div class="party-box-title" style="color:#0f2744;">Supplier / Vendor Details</div>
        <div class="party-name" style="color:#0f2744;">${_esc(supplier.name || 'Supplier')}</div>
        <div class="party-detail"><strong>Company:</strong> ${_esc(supplier.company || '-')}</div>
        <div class="party-detail"><strong>Contact:</strong> ${_esc(supplier.phone || '-')}</div>
        <div class="party-detail"><strong>Location:</strong> ${_esc(supplier.city || supplier.address || '-')}</div>
        <div class="party-detail"><strong>Currency:</strong> ${cur}</div>
      </div>
      <div class="party-box">
        <div class="party-box-title">Billed &amp; Delivered To</div>
        <div class="party-name">${RH_BRAND.name}</div>
        <div class="party-detail"><strong>Facility:</strong> Main Warehouse &amp; Sorting Floor</div>
        <div class="party-detail"><strong>Location:</strong> Karachi, Pakistan</div>
        <div class="party-detail"><strong>Phone:</strong> ${RH_BRAND.phone}</div>
        <div class="party-detail"><strong>Email:</strong> ${RH_BRAND.email}</div>
      </div>
    </div>

    <table class="doc-table">
      <thead>
        <tr>
          <th style="width:30px;" class="center">#</th>
          <th>Stock Description / Article</th>
          <th style="width:65px;" class="center">Qty</th>
          <th style="width:95px;" class="num">Rate</th>
          <th style="width:110px;" class="num">Amount</th>
        </tr>
      </thead>
      <tbody>${itemsHtml}</tbody>
    </table>

    <div class="summary-section">
      <div class="totals-box">
        <div class="totals-row"><span>Items Subtotal:</span><span>${formatCurrency(subtotal, cur)}</span></div>
        ${transport > 0 ? `<div class="totals-row"><span>Freight / Transport:</span><span>${formatCurrency(transport, cur)}</span></div>` : ''}
        ${loading > 0 ? `<div class="totals-row"><span>Loading / Labor:</span><span>${formatCurrency(loading, cur)}</span></div>` : ''}
        ${tax > 0 ? `<div class="totals-row"><span>Tax / Duties:</span><span>${formatCurrency(tax, cur)}</span></div>` : ''}
        ${discount > 0 ? `<div class="totals-row" style="color:#be123c;"><span>Discount:</span><span>-${formatCurrency(discount, cur)}</span></div>` : ''}
        <div class="totals-row grand-total"><span>TOTAL INVOICE:</span><span>${formatCurrency(grandTotal, cur)}</span></div>
      </div>
    </div>

    ${paymentsSection}

    <div class="balance-status-strip">
      <div>
        <div class="balance-status-label">Invoice Balance Status</div>
        <div style="font-size:10.5px; color:#52525b;">Total Invoiced: ${formatCurrency(grandTotal, cur)} &bull; Total Paid: ${formatCurrency(paid, cur)}</div>
      </div>
      <div class="balance-status-val ${remaining > 0 ? 'due' : 'cleared'}">
        ${remaining > 0 ? 'OUTSTANDING: ' + formatCurrency(remaining, cur) : 'PAID IN FULL'}
      </div>
    </div>

    ${transaction.notes ? `<div class="notes-box"><strong>Notes / Instructions:</strong> ${_esc(transaction.notes)}</div>` : ''}

    <div class="signature-grid">
      <div class="signature-box">
        <div class="signature-title">Authorized Officer</div>
        <div class="signature-sub">For Rags Heaven</div>
      </div>
      <div class="signature-box">
        <div class="signature-title">Supplier Signature / Stamp</div>
        <div class="signature-sub">${_esc(supplier.name || 'Vendor Signature')}</div>
      </div>
    </div>
  `;

  return _docShell('Purchase Invoice - ' + docNo, body, 'theme-supplier');
}

// ═══════════════════════════════════════════════════════════════════════
// 2. SALES INVOICE (Buyers)
// ═══════════════════════════════════════════════════════════════════════
function buildSalesInvoice(buyer, transaction, payments) {
  buyer = buyer || {};
  transaction = transaction || {};
  payments = payments || [];

  const cur = buyer.currency || 'PKR';
  const docNo = transaction.invoice_no || 'INV-DRAFT';
  const docDate = transaction.date || new Date().toISOString();

  const items = transaction.items || [];
  let itemsHtml = items.map((it, idx) => {
    const qty = parseFloat(it.qty) || 0;
    const rate = parseFloat(it.rate) || 0;
    const disc = parseFloat(it.discount) || 0;
    const amt = parseFloat(it.amount) || Math.max(0, (qty * rate) - disc);
    return `<tr>
      <td class="center">${idx + 1}</td>
      <td style="font-weight:600;">${_esc(it.desc || it.name || 'Garment article')}</td>
      <td class="center">${qty}</td>
      <td class="num">${formatCurrency(rate, cur)}</td>
      <td class="num" style="color:#71717a;">${disc > 0 ? formatCurrency(disc, cur) : '-'}</td>
      <td class="num" style="font-weight:700;">${formatCurrency(amt, cur)}</td>
    </tr>`;
  }).join('');

  if (!itemsHtml) {
    itemsHtml = '<tr><td colspan="6" style="text-align:center;color:#94a3b8;padding:16px;">No articles specified.</td></tr>';
  }

  const subtotal = parseFloat(transaction.subtotal) || 0;
  const transport = parseFloat(transaction.transport) || 0;
  const tax = parseFloat(transaction.tax) || 0;
  const discount = parseFloat(transaction.discount) || 0;
  const grandTotal = parseFloat(transaction.grand_total) || 0;

  const paid = payments.reduce((sum, p) => sum + (parseFloat(p.amount) || 0), 0);
  const remaining = Math.max(0, grandTotal - paid);

  let paymentsSection = '';
  if (payments.length > 0) {
    const payRows = payments.map((p, idx) => `<tr>
      <td class="center">${idx + 1}</td>
      <td style="font-weight:700;">${_esc(p.receipt_no || 'REC')}</td>
      <td>${_formatDate(p.date)}</td>
      <td>${_esc(p.payment_method || 'Cash')} ${p.bank_ref ? ' - Ref: ' + _esc(p.bank_ref) : ''}</td>
      <td class="num" style="font-weight:700; color:#059669;">${formatCurrency(p.amount, cur)}</td>
    </tr>`).join('');

    paymentsSection = `
      <div style="margin-top:14px; margin-bottom:12px;">
        <div style="font-size:10px; font-weight:800; text-transform:uppercase; color:#000; margin-bottom:4px;">Customer Receipts Recorded</div>
        <table class="doc-table">
          <thead>
            <tr>
              <th style="width:30px;" class="center">#</th>
              <th>Receipt #</th>
              <th>Date</th>
              <th>Method / Ref</th>
              <th class="num">Amount Received</th>
            </tr>
          </thead>
          <tbody>${payRows}</tbody>
        </table>
      </div>
    `;
  }

  const body = `
    ${_renderHeader('SALES INVOICE', docNo, docDate, 'Commercial Customer Pack &bull; Outbound Goods')}

    <div class="party-grid">
      <div class="party-box party-primary">
        <div class="party-box-title" style="color:#064e3b;">Client / Buyer Information</div>
        <div class="party-name" style="color:#064e3b;">${_esc(buyer.name || 'Client')}</div>
        <div class="party-detail"><strong>Company:</strong> ${_esc(buyer.company || '-')}</div>
        <div class="party-detail"><strong>Contact:</strong> ${_esc(buyer.phone || '-')}</div>
        <div class="party-detail"><strong>Shipping:</strong> ${_esc(buyer.city || buyer.address || '-')}</div>
        <div class="party-detail"><strong>Billing Currency:</strong> ${cur}</div>
      </div>
      <div class="party-box">
        <div class="party-box-title">Issued &amp; Dispatched From</div>
        <div class="party-name">${RH_BRAND.name}</div>
        <div class="party-detail"><strong>Dispatch:</strong> Sorting &amp; Export Facility</div>
        <div class="party-detail"><strong>Location:</strong> Karachi, Pakistan</div>
        <div class="party-detail"><strong>Phone:</strong> ${RH_BRAND.phone}</div>
        <div class="party-detail"><strong>Website:</strong> ${RH_BRAND.website}</div>
      </div>
    </div>

    <table class="doc-table">
      <thead>
        <tr>
          <th style="width:30px;" class="center">#</th>
          <th>Article Description / Garment SKU</th>
          <th style="width:60px;" class="center">Qty</th>
          <th style="width:90px;" class="num">Rate</th>
          <th style="width:75px;" class="num">Disc</th>
          <th style="width:105px;" class="num">Amount</th>
        </tr>
      </thead>
      <tbody>${itemsHtml}</tbody>
    </table>

    <div class="summary-section">
      <div class="totals-box">
        <div class="totals-row"><span>Articles Subtotal:</span><span>${formatCurrency(subtotal, cur)}</span></div>
        ${transport > 0 ? `<div class="totals-row"><span>Delivery / Courier:</span><span>${formatCurrency(transport, cur)}</span></div>` : ''}
        ${tax > 0 ? `<div class="totals-row"><span>Sales Tax / VAT:</span><span>${formatCurrency(tax, cur)}</span></div>` : ''}
        ${discount > 0 ? `<div class="totals-row" style="color:#be123c;"><span>Special Discount:</span><span>-${formatCurrency(discount, cur)}</span></div>` : ''}
        <div class="totals-row grand-total"><span>TOTAL INVOICE:</span><span>${formatCurrency(grandTotal, cur)}</span></div>
      </div>
    </div>

    ${paymentsSection}

    <div class="balance-status-strip">
      <div>
        <div class="balance-status-label">Receivable Status</div>
        <div style="font-size:10.5px; color:#52525b;">Invoice Total: ${formatCurrency(grandTotal, cur)} &bull; Amount Received: ${formatCurrency(paid, cur)}</div>
      </div>
      <div class="balance-status-val ${remaining > 0 ? 'due' : 'cleared'}">
        ${remaining > 0 ? 'RECEIVABLE DUE: ' + formatCurrency(remaining, cur) : 'PAID IN FULL'}
      </div>
    </div>

    ${transaction.notes ? `<div class="notes-box"><strong>Delivery / Order Notes:</strong> ${_esc(transaction.notes)}</div>` : ''}

    <div class="signature-grid">
      <div class="signature-box">
        <div class="signature-title">Authorized Dispatch Manager</div>
        <div class="signature-sub">For Rags Heaven</div>
      </div>
      <div class="signature-box">
        <div class="signature-title">Received By Client</div>
        <div class="signature-sub">${_esc(buyer.name || 'Authorized Recipient')}</div>
      </div>
    </div>
  `;

  return _docShell('Sales Invoice - ' + docNo, body, 'theme-buyer');
}

