// ═══════════════════════════════════════════════════════════════════════
// 5. SUPPLIER LEDGER STATEMENT
// ═══════════════════════════════════════════════════════════════════════
function buildSupplierLedger(supplier, transactions, payments) {
  supplier = supplier || {};
  transactions = transactions || [];
  payments = payments || [];

  const cur = supplier.currency || 'PKR';
  const openBal = parseFloat(supplier.opening_balance) || 0;

  const rows = [];
  rows.push({
    date: supplier.created_at ? supplier.created_at.slice(0, 10) : 'Opening',
    ref: 'OPENING',
    desc: 'Opening Balance on Supplier Setup',
    debit: openBal,
    credit: 0
  });

  transactions.forEach(tx => {
    rows.push({
      date: tx.date,
      ref: tx.invoice_no,
      desc: 'Purchase Invoice: ' + (tx.notes || (tx.items && tx.items.length ? tx.items[0].desc : 'Stock purchase')),
      debit: parseFloat(tx.grand_total) || 0,
      credit: 0
    });
  });

  payments.forEach(pm => {
    rows.push({
      date: pm.date,
      ref: pm.receipt_no,
      desc: `Payment (${pm.payment_method})` + (pm.bank_ref ? ' Ref: ' + pm.bank_ref : ''),
      debit: 0,
      credit: parseFloat(pm.amount) || 0
    });
  });

  rows.sort((a, b) => (a.date || '').localeCompare(b.date || ''));

  let runningBal = 0;
  let totalDebit = 0;
  let totalCredit = 0;

  const tableRows = rows.map((r, i) => {
    if (i === 0) {
      runningBal = r.debit;
    } else {
      runningBal += (r.debit - r.credit);
      totalDebit += r.debit;
      totalCredit += r.credit;
    }

    return `<tr>
      <td>${_formatDate(r.date)}</td>
      <td style="font-weight:700; font-family:monospace; color:#0f2744;">${_esc(r.ref)}</td>
      <td>${_esc(r.desc)}</td>
      <td class="num" style="color:#be123c; font-weight:700;">${r.debit > 0 ? formatCurrency(r.debit, cur) : '-'}</td>
      <td class="num" style="color:#059669; font-weight:700;">${r.credit > 0 ? formatCurrency(r.credit, cur) : '-'}</td>
      <td class="num" style="font-weight:800; color:#0f2744;">${formatCurrency(runningBal, cur)}</td>
    </tr>`;
  }).join('');

  const body = `
    ${_renderHeader('SUPPLIER FINANCIAL STATEMENT', 'LEDGER-' + (supplier.id ? supplier.id.slice(0, 6) : '001'), new Date().toISOString(), 'Vendor Account History &bull; Complete Ledger')}

    <div class="party-box party-primary" style="margin-bottom:14px;">
      <div class="party-box-title" style="color:#0f2744;">Supplier Statement of Account</div>
      <div style="display:flex; justify-content:space-between; align-items:flex-start;">
        <div>
          <div class="party-name" style="color:#0f2744;">${_esc(supplier.name)}</div>
          <div class="party-detail"><strong>Company:</strong> ${_esc(supplier.company || '-')} &bull; <strong>Phone:</strong> ${_esc(supplier.phone || '-')}</div>
          <div class="party-detail"><strong>Location:</strong> ${_esc(supplier.city || supplier.address || '-')} &bull; <strong>Currency:</strong> ${cur}</div>
        </div>
        <div style="text-align:right;">
          <div style="font-size:10px; color:#71717a; font-weight:700; text-transform:uppercase;">Current Net Dues</div>
          <div style="font-size:18px; font-weight:800; color:#be123c;">${formatCurrency(runningBal, cur)}</div>
        </div>
      </div>
    </div>

    <table class="doc-table">
      <thead>
        <tr>
          <th style="width:75px;">Date</th>
          <th style="width:115px;">Reference #</th>
          <th>Description / Particulars</th>
          <th style="width:95px;" class="num">Debit (Bills)</th>
          <th style="width:95px;" class="num">Credit (Paid)</th>
          <th style="width:105px;" class="num">Balance</th>
        </tr>
      </thead>
      <tbody>${tableRows}</tbody>
    </table>

    <div class="summary-section">
      <div class="totals-box">
        <div class="totals-row"><span>Total Invoiced Purchases:</span><span style="color:#be123c;">${formatCurrency(totalDebit, cur)}</span></div>
        <div class="totals-row"><span>Total Payments Settled:</span><span style="color:#059669;">${formatCurrency(totalCredit, cur)}</span></div>
        <div class="totals-row grand-total"><span>NET OUTSTANDING DUE:</span><span>${formatCurrency(runningBal, cur)}</span></div>
      </div>
    </div>

    <div class="signature-grid" style="margin-top:30px;">
      <div class="signature-box">
        <div class="signature-title">Prepared By (Accounts)</div>
        <div class="signature-sub">Rags Heaven</div>
      </div>
      <div class="signature-box">
        <div class="signature-title">Verified By Management</div>
        <div class="signature-sub">Authorized Signature &amp; Stamp</div>
      </div>
    </div>
  `;

  return _docShell('Supplier Ledger - ' + (supplier.name || 'Statement'), body, 'theme-supplier');
}

